function(container, apiUrl, tables) {
  // テーブルインデックスマッピング
  const tableMap = {};
  tables.forEach((t, i) => {
    tableMap[t.tableName] = i;
  });

  // 初期データ
  let allContracts = [];
  let allHistory = [];
  let allBilling = [];
  let allBillingDetails = [];
  let allCustomers = [];
  let filteredHistory = [];
  let selectedHistoryId = null;

  // ========== データ取得 ==========
  async function loadData() {
    try {
      if (tableMap['契約'] !== undefined) {
        allContracts = await window.aivicApi.list(tableMap['契約']) || [];
      }
      if (tableMap['契約履歴'] !== undefined) {
        allHistory = await window.aivicApi.list(tableMap['契約履歴']) || [];
      }
      if (tableMap['請求'] !== undefined) {
        allBilling = await window.aivicApi.list(tableMap['請求']) || [];
      }
      if (tableMap['請求明細'] !== undefined) {
        allBillingDetails = await window.aivicApi.list(tableMap['請求明細']) || [];
      }
      if (tableMap['顧客'] !== undefined) {
        allCustomers = await window.aivicApi.list(tableMap['顧客']) || [];
      }
      updateKPIs();
      renderCharts();
      renderTimeline([]);
      renderBillingDetail([]);
    } catch (e) {
      console.error('Data load error:', e);
    }
  }

  // ========== KPI 更新 ==========
  function updateKPIs() {
    const totalBilling = allBilling.reduce((sum, b) => sum + (b.請求金額 || 0), 0);
    const verifiedCount = allBillingDetails.filter(d => d.検証ステータス === '検証済み').length;
    const discrepancyCount = allBillingDetails.filter(d => d.検証ステータス === '差異検出').length;
    const totalDetails = allBillingDetails.length;
    const reconciliationRate = totalDetails > 0 ? Math.round((verifiedCount / totalDetails) * 100) : 0;

    container.querySelector('[data-testid="kpi-total-billing"]').textContent = `¥${totalBilling.toLocaleString()}`;
    container.querySelector('[data-testid="kpi-verified-count"]').textContent = verifiedCount;
    container.querySelector('[data-testid="kpi-discrepancy-count"]').textContent = discrepancyCount;
    container.querySelector('[data-testid="kpi-reconciliation-rate"]').textContent = `${reconciliationRate}%`;
  }

  // ========== グラフ描画 ==========
  function renderCharts() {
    // 月別請求金額
    const monthlyData = {};
    allBilling.forEach(b => {
      const month = b.請求年月 || '不明';
      monthlyData[month] = (monthlyData[month] || 0) + (b.請求金額 || 0);
    });
    const months = Object.keys(monthlyData).sort();
    const amounts = months.map(m => monthlyData[m]);

    const ctxMonthly = container.querySelector('#chart-monthly-billing').getContext('2d');
    new window.Chart(ctxMonthly, {
      type: 'bar',
      data: {
        labels: months,
        datasets: [{
          label: '請求金額',
          data: amounts,
          backgroundColor: '#d4a574',
          borderColor: '#c9915f',
          borderWidth: 1
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: { legend: { display: false } },
        scales: {
          y: { beginAtZero: true, ticks: { color: '#9fb0d1', font: { size: 10 } }, grid: { color: 'rgba(255,255,255,0.05)' } },
          x: { ticks: { color: '#9fb0d1', font: { size: 10 } }, grid: { display: false } }
        }
      }
    });

    // 検証ステータス分布
    const statusCounts = {};
    allBillingDetails.forEach(d => {
      const status = d.検証ステータス || '不明';
      statusCounts[status] = (statusCounts[status] || 0) + 1;
    });
    const statuses = Object.keys(statusCounts);
    const counts = statuses.map(s => statusCounts[s]);
    const colors = ['#9fb0d1', '#4ade80', '#ff6b6b', '#fbbf24'];

    const ctxStatus = container.querySelector('#chart-verification-status').getContext('2d');
    new window.Chart(ctxStatus, {
      type: 'doughnut',
      data: {
        labels: statuses,
        datasets: [{
          data: counts,
          backgroundColor: colors.slice(0, statuses.length),
          borderColor: 'var(--bg-card)',
          borderWidth: 2
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { position: 'bottom', labels: { color: '#9fb0d1', font: { size: 10 }, padding: 8 } }
        }
      }
    });
  }

  // ========== タイムライン描画 ==========
  function renderTimeline(historyList) {
    const container_tl = container.querySelector('#timeline-container');
    container_tl.innerHTML = '';

    if (historyList.length === 0) {
      container_tl.innerHTML = '<div style="font-size: 12px; color: var(--text-muted); text-align: center; padding: 20px;">該当する履歴がありません</div>';
      return;
    }

    historyList.forEach((hist, idx) => {
      const contract = allContracts.find(c => c.契約ID === hist.契約ID);
      const customer = contract ? allCustomers.find(cust => cust.顧客ID === contract.顧客企業ID) : null;
      const hasDiscrepancy = hist.請求検証ステータス === '不一致';

      const item = document.createElement('div');
      item.style.cssText = `
        padding: 10px;
        margin-bottom: 8px;
        border-left: 3px solid ${hasDiscrepancy ? '#ff6b6b' : '#4ade80'};
        background: rgba(0,0,0,0.2);
        border-radius: 4px;
        cursor: pointer;
        transition: background 0.2s;
      `;
      item.className = 'timeline-item';
      item.dataset.historyId = hist.契約履歴ID;

      const dateStr = hist.作成日時 ? new Date(hist.作成日時).toLocaleDateString('ja-JP') : '不明';
      const changeType = hist.変更種別 || '不明';
      const fieldName = hist.変更フィールド名 || '';

      item.innerHTML = `
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">${dateStr}</div>
        <div style="font-size: 12px; font-weight: 500; color: var(--text); margin-bottom: 4px;">${changeType}${fieldName ? ` - ${fieldName}` : ''}</div>
        <div style="font-size: 11px; color: var(--text-muted);">${customer ? customer.顧客名 : '顧客不明'} / ${contract ? contract.契約名 : '契約不明'}</div>
        ${hasDiscrepancy ? `<div style="font-size: 10px; color: #ff6b6b; margin-top: 4px; font-weight: 500;">⚠ 請求との不一致</div>` : ''}
      `;

      item.addEventListener('click', () => {
        document.querySelectorAll('.timeline-item').forEach(el => el.style.background = 'rgba(0,0,0,0.2)');
        item.style.background = 'rgba(212, 165, 116, 0.2)';
        selectedHistoryId = hist.契約履歴ID;
        showDetailModal(hist);
        renderBillingDetail(hist.契約ID);
      });

      container_tl.appendChild(item);
    });
  }

  // ========== 請求明細描画 ==========
  function renderBillingDetail(contractId) {
    const container_bd = container.querySelector('#billing-detail-container');
    container_bd.innerHTML = '';

    if (!contractId) {
      container_bd.innerHTML = '<div style="font-size: 12px; color: var(--text-muted); text-align: center; padding: 20px;">履歴を選択してください</div>';
      return;
    }

    const details = allBillingDetails.filter(d => d.契約ID === contractId);
    if (details.length === 0) {
      container_bd.innerHTML = '<div style="font-size: 12px; color: var(--text-muted); text-align: center; padding: 20px;">対応する請求明細がありません</div>';
      return;
    }

    details.forEach(detail => {
      const statusColor = detail.検証ステータス === '検証済み' ? '#4ade80' : detail.検証ステータス === '差異検出' ? '#ff6b6b' : '#9fb0d1';
      const item = document.createElement('div');
      item.style.cssText = `
        padding: 10px;
        margin-bottom: 8px;
        border-left: 3px solid ${statusColor};
        background: rgba(0,0,0,0.2);
        border-radius: 4px;
      `;

      item.innerHTML = `
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">${detail.明細種別 || '不明'}</div>
        <div style="font-size: 12px; font-weight: 500; color: var(--text); margin-bottom: 4px;">¥${(detail.金額 || 0).toLocaleString()}</div>
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">数量: ${detail.数量 || 0} × 単価: ¥${(detail.単価 || 0).toLocaleString()}</div>
        <div style="font-size: 10px; padding: 4px 6px; background: ${statusColor}33; color: ${statusColor}; border-radius: 3px; display: inline-block;">
          ${detail.検証ステータス || '不明'}
        </div>
        ${detail.差異理由 ? `<div style="font-size: 10px; color: #ff6b6b; margin-top: 4px;">理由: ${detail.差異理由}</div>` : ''}
      `;

      container_bd.appendChild(item);
    });
  }

  // ========== 詳細モーダル表示 ==========
  function showDetailModal(hist) {
    const modal = container.querySelector('#detail-modal');
    const content = container.querySelector('#detail-content');

    const contract = allContracts.find(c => c.契約ID === hist.契約ID);
    const customer = contract ? allCustomers.find(cust => cust.顧客ID === contract.顧客企業ID) : null;

    let beforeVal = '不明';
    let afterVal = '不明';
    try {
      if (hist.変更前値) beforeVal = typeof hist.変更前値 === 'string' ? hist.変更前値 : JSON.stringify(hist.変更前値);
      if (hist.変更後値) afterVal = typeof hist.変更後値 === 'string' ? hist.変更後値 : JSON.stringify(hist.変更後値);
    } catch (e) {}

    content.innerHTML = `
      <div style="margin-bottom: 12px;">
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">顧客</div>
        <div style="font-size: 12px; color: var(--text);">${customer ? customer.顧客名 : '不明'}</div>
      </div>
      <div style="margin-bottom: 12px;">
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">契約</div>
        <div style="font-size: 12px; color: var(--text);">${contract ? contract.契約名 : '不明'}</div>
      </div>
      <div style="margin-bottom: 12px;">
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">変更種別</div>
        <div style="font-size: 12px; color: var(--text);">${hist.変更種別 || '不明'}</div>
      </div>
      <div style="margin-bottom: 12px;">
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">変更フィールド</div>
        <div style="font-size: 12px; color: var(--text);">${hist.変更フィールド名 || '不明'}</div>
      </div>
      <div style="margin-bottom: 12px;">
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">変更前</div>
        <div style="font-size: 12px; color: var(--text); word-break: break-all;">${beforeVal}</div>
      </div>
      <div style="margin-bottom: 12px;">
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">変更後</div>
        <div style="font-size: 12px; color: var(--text); word-break: break-all;">${afterVal}</div>
      </div>
      <div style="margin-bottom: 12px;">
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">請求検証ステータス</div>
        <div style="font-size: 12px; color: ${hist.請求検証ステータス === '不一致' ? '#ff6b6b' : '#4ade80'}; font-weight: 500;">${hist.請求検証ステータス || '不明'}</div>
      </div>
      <div style="margin-bottom: 12px;">
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">変更日時</div>
        <div style="font-size: 12px; color: var(--text);">${hist.作成日時 ? new Date(hist.作成日時).toLocaleString('ja-JP') : '不明'}</div>
      </div>
      ${hist.備考 ? `<div style="margin-bottom: 12px;">
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">備考</div>
        <div style="font-size: 12px; color: var(--text);">${hist.備考}</div>
      </div>` : ''}
    `;

    modal.style.display = 'flex';
  }

  // ========== 検索処理 ==========
  function performSearch() {
    const customerFilter = container.querySelector('#filter-customer').value.toLowerCase();
    const contractIdFilter = container.querySelector('#filter-contract-id').value.toLowerCase();
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;

    filteredHistory = allHistory.filter(hist => {
      const contract = allContracts.find(c => c.契約ID === hist.契約ID);
      if (!contract) return false;

      const customer = allCustomers.find(cust => cust.顧客ID === contract.顧客企業ID);
      if (customerFilter && (!customer || !customer.顧客名.toLowerCase().includes(customerFilter))) return false;
      if (contractIdFilter && !contract.契約ID.toLowerCase().includes(contractIdFilter)) return false;

      if (startDate && hist.作成日時 < startDate) return false;
      if (endDate && hist.作成日時 > endDate + 'T23:59:59') return false;

      return true;
    });

    renderTimeline(filteredHistory);
    renderBillingDetail(null);
  }

  // ========== イベントリスナー ==========
  container.querySelector('#btn-search').addEventListener('click', performSearch);

  container.querySelector('#btn-close-detail').addEventListener('click', () => {
    container.querySelector('#detail-modal').style.display = 'none';
  });

  container.querySelector('#btn-detail-cancel').addEventListener('click', () => {
    container.querySelector('#detail-modal').style.display = 'none';
  });

  container.querySelector('#btn-verify-detail').addEventListener('click', async () => {
    if (!selectedHistoryId) return;
    const hist = allHistory.find(h => h.契約履歴ID === selectedHistoryId);
    if (!hist) return;

    try {
      await window.aivicApi.update(tableMap['契約履歴'], selectedHistoryId, {
        請求検証ステータス: '検証済み'
      });
      await loadData();
      performSearch();
      container.querySelector('#detail-modal').style.display = 'none';
    } catch (e) {
      console.error('Update error:', e);
    }
  });

  // 初期ロード
  loadData();
}

function(container, apiUrl, tables) {
  const contractTable = tables[0]; // 契約テーブル
  const historyTable = tables[1];  // 契約履歴テーブル
  const billingTable = tables[2];  // 請求テーブル
  const userTable = tables[3];     // ユーザーテーブル
  const customerTable = tables[4]; // 顧客テーブル

  let currentContract = null;
  let selectedFiles = [];

  // ===== DOM 要素取得 =====
  const searchInput = container.querySelector('[data-testid="contract-id-input"]');
  const searchBtn = container.querySelector('[data-testid="search-button"]');
  const currentContractDisplay = container.querySelector('#current-contract-display');
  const changeForm = container.querySelector('#change-form');
  const changePreview = container.querySelector('#change-preview');
  const saveBtn = container.querySelector('[data-testid="save-button"]');
  const submitBtn = container.querySelector('[data-testid="submit-button"]');
  const cancelBtn = container.querySelector('[data-testid="cancel-button"]');
  const fileDropZone = container.querySelector('#file-drop-zone');
  const fileInput = container.querySelector('[data-testid="file-upload"]');
  const fileList = container.querySelector('#file-list');
  const messageContainer = container.querySelector('#message-container');

  // ===== ユーティリティ関数 =====
  function showMessage(text, type = 'info') {
    const msg = document.createElement('div');
    msg.style.cssText = `
      padding: 10px 12px;
      border-radius: 4px;
      font-size: 12px;
      margin-bottom: 6px;
      animation: slideIn 0.3s ease-out;
      ${type === 'success' ? 'background: rgba(76, 175, 80, 0.2); border-left: 3px solid #4caf50; color: #a5d6a7;' : ''}
      ${type === 'error' ? 'background: rgba(244, 67, 54, 0.2); border-left: 3px solid #f44336; color: #ef9a9a;' : ''}
      ${type === 'info' ? 'background: rgba(33, 150, 243, 0.2); border-left: 3px solid #2196f3; color: #90caf9;' : ''}
    `;
    msg.textContent = text;
    messageContainer.appendChild(msg);
    setTimeout(() => msg.remove(), 4000);
  }

  function formatCurrency(value) {
    return new Intl.NumberFormat('ja-JP', { style: 'currency', currency: 'JPY' }).format(value);
  }

  function formatDate(dateStr) {
    if (!dateStr) return '-';
    const d = new Date(dateStr);
    return d.toLocaleDateString('ja-JP');
  }

  // ===== 契約検索 =====
  async function searchContract() {
    const query = searchInput.value.trim();
    if (!query) {
      showMessage('契約ID または顧客名を入力してください', 'info');
      return;
    }

    try {
      const contracts = await window.aivicApi.list(0); // 契約テーブル
      if (!contracts) {
        showMessage('契約データの取得に失敗しました', 'error');
        return;
      }

      const found = contracts.find(c =>
        c.id?.includes(query) ||
        c.contractName?.includes(query) ||
        c.customerId?.includes(query)
      );

      if (!found) {
        showMessage('該当する契約が見つかりません', 'info');
        currentContractDisplay.innerHTML = '<div style="color: var(--text-muted); padding: 16px; text-align: center;">契約が見つかりません</div>';
        currentContract = null;
        return;
      }

      currentContract = found;
      displayCurrentContract(found);
      resetForm();
      showMessage('契約を読み込みました', 'success');
    } catch (err) {
      showMessage('検索エラー: ' + err.message, 'error');
    }
  }

  function displayCurrentContract(contract) {
    const customers = customerTable?.records || [];
    const customer = customers.find(c => c.id === contract.customerId);

    currentContractDisplay.innerHTML = `
      <div style="display: grid; gap: 8px; font-size: 12px;">
        <div>
          <div style="color: var(--text-muted); font-size: 11px;">契約ID</div>
          <div style="color: var(--text); font-weight: 500;">${contract.id || '-'}</div>
        </div>
        <div>
          <div style="color: var(--text-muted); font-size: 11px;">契約名</div>
          <div style="color: var(--text); font-weight: 500;">${contract.contractName || '-'}</div>
        </div>
        <div>
          <div style="color: var(--text-muted); font-size: 11px;">顧客名</div>
          <div style="color: var(--text); font-weight: 500;">${customer?.customerName || '-'}</div>
        </div>
        <div>
          <div style="color: var(--text-muted); font-size: 11px;">契約ステータス</div>
          <div style="color: var(--text); font-weight: 500;">${contract.contractStatus || '-'}</div>
        </div>
        <div>
          <div style="color: var(--text-muted); font-size: 11px;">契約期間</div>
          <div style="color: var(--text); font-weight: 500;">${formatDate(contract.contractStartDate)} ～ ${formatDate(contract.contractEndDate)}</div>
        </div>
        <div>
          <div style="color: var(--text-muted); font-size: 11px;">契約金額</div>
          <div style="color: var(--text); font-weight: 500;">${formatCurrency(contract.contractAmount || 0)}</div>
        </div>
        <div>
          <div style="color: var(--text-muted); font-size: 11px;">契約内容</div>
          <div style="color: var(--text); white-space: pre-wrap; word-break: break-word; max-height: 100px; overflow-y: auto;">${contract.contractContent || '-'}</div>
        </div>
      </div>
    `;
  }

  function resetForm() {
    changeForm.reset();
    selectedFiles = [];
    fileList.innerHTML = '';
    updatePreview();
  }

  // ===== 変更プレビュー =====
  function updatePreview() {
    const formData = new FormData(changeForm);
    const changes = {
      changeType: formData.get('changeType') || '未選択',
      newPlan: formData.get('newPlan') || '未選択',
      newQuantity: formData.get('newQuantity') || '-',
      newPrice: formData.get('newPrice') ? formatCurrency(parseInt(formData.get('newPrice'))) : '-',
      changeStartDate: formatDate(formData.get('changeStartDate')),
      changeEndDate: formatDate(formData.get('changeEndDate')),
      billingReflection: formData.get('billingReflection') || '未選択',
      changeReason: formData.get('changeReason') || '（未入力）',
    };

    const preview = `変更種別: ${changes.changeType}
新プラン: ${changes.newPlan}
数量: ${changes.newQuantity}
料金: ${changes.newPrice}
開始日: ${changes.changeStartDate}
終了日: ${changes.changeEndDate}
請求反映: ${changes.billingReflection}
理由: ${changes.changeReason}`;

    changePreview.textContent = preview;
  }

  // ===== ファイルアップロード =====
  fileDropZone.addEventListener('dragover', (e) => {
    e.preventDefault();
    fileDropZone.style.background = 'rgba(255, 215, 0, 0.1)';
    fileDropZone.style.borderColor = 'rgba(255, 215, 0, 0.5)';
  });

  fileDropZone.addEventListener('dragleave', () => {
    fileDropZone.style.background = 'rgba(0,0,0,0.15)';
    fileDropZone.style.borderColor = 'rgba(255,255,255,0.25)';
  });

  fileDropZone.addEventListener('drop', (e) => {
    e.preventDefault();
    fileDropZone.style.background = 'rgba(0,0,0,0.15)';
    fileDropZone.style.borderColor = 'rgba(255,255,255,0.25)';
    handleFiles(e.dataTransfer.files);
  });

  fileDropZone.addEventListener('click', () => fileInput.click());

  fileInput.addEventListener('change', (e) => {
    handleFiles(e.target.files);
  });

  function handleFiles(files) {
    selectedFiles = Array.from(files);
    updateFileList();
  }

  function updateFileList() {
    fileList.innerHTML = selectedFiles
      .map((f, i) => `<div style="margin: 2px 0;">📎 ${f.name} (${(f.size / 1024).toFixed(1)} KB) <button type="button" data-index="${i}" class="remove-file-btn" style="background: none; border: none; color: #ff6b6b; cursor: pointer; font-size: 11px; padding: 0; margin-left: 4px;">削除</button></div>`)
      .join('');

    container.querySelectorAll('.remove-file-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.preventDefault();
        const idx = parseInt(e.target.dataset.index);
        selectedFiles.splice(idx, 1);
        updateFileList();
      });
    });
  }

  // ===== フォーム入力監視 =====
  changeForm.addEventListener('change', updatePreview);
  changeForm.addEventListener('input', updatePreview);

  // ===== 保存処理 =====
  saveBtn.addEventListener('click', async (e) => {
    e.preventDefault();
    if (!currentContract) {
      showMessage('先に契約を検索してください', 'info');
      return;
    }

    const formData = new FormData(changeForm);
    const changeData = {
      contractId: currentContract.id,
      changeType: formData.get('changeType'),
      newPlan: formData.get('newPlan'),
      newQuantity: parseInt(formData.get('newQuantity')) || null,
      newPrice: parseInt(formData.get('newPrice')) || null,
      changeStartDate: formData.get('changeStartDate'),
      changeEndDate: formData.get('changeEndDate'),
      billingReflection: formData.get('billingReflection'),
      changeReason: formData.get('changeReason'),
      attachmentCount: selectedFiles.length,
    };

    // バリデーション
    if (!changeData.changeType) {
      showMessage('変更種別を選択してください', 'error');
      return;
    }
    if (!changeData.changeStartDate) {
      showMessage('変更開始日を入力してください', 'error');
      return;
    }

    try {
      // 契約履歴に記録
      const historyRecord = {
        contractId: currentContract.id,
        changeType: changeData.changeType,
        changeBefore: JSON.stringify({
          plan: currentContract.contractName,
          amount: currentContract.contractAmount,
        }),
        changeAfter: JSON.stringify({
          plan: changeData.newPlan,
          amount: changeData.newPrice,
        }),
        changeField: 'multiple',
        billingVerificationStatus: 'pending',
        creatorId: userTable?.records?.[0]?.id || 'system',
        remarks: changeData.changeReason,
      };

      const saved = await window.aivicApi.save(1, historyRecord); // 契約履歴テーブル
      if (saved) {
        showMessage('変更内容を保存しました', 'success');
        resetForm();
      } else {
        showMessage('保存に失敗しました', 'error');
      }
    } catch (err) {
      showMessage('保存エラー: ' + err.message, 'error');
    }
  });

  // ===== 申請処理 =====
  submitBtn.addEventListener('click', async (e) => {
    e.preventDefault();
    if (!currentContract) {
      showMessage('先に契約を検索してください', 'info');
      return;
    }

    const formData = new FormData(changeForm);
    if (!formData.get('changeType') || !formData.get('changeStartDate')) {
      showMessage('必須項目を入力してください', 'error');
      return;
    }

    try {
      // 変更申請を履歴に記録
      const historyRecord = {
        contractId: currentContract.id,
        changeType: formData.get('changeType'),
        changeBefore: JSON.stringify({ status: 'pending' }),
        changeAfter: JSON.stringify({ status: 'submitted' }),
        changeField: 'status',
        billingVerificationStatus: 'pending',
        creatorId: userTable?.records?.[0]?.id || 'system',
        remarks: formData.get('changeReason'),
      };

      const saved = await window.aivicApi.save(1, historyRecord);
      if (saved) {
        showMessage('変更申請を送信しました。審査をお待ちください。', 'success');
        resetForm();
        currentContract = null;
        currentContractDisplay.innerHTML = '<div style="color: var(--text-muted); padding: 16px; text-align: center;">契約を検索してください</div>';
      } else {
        showMessage('申請に失敗しました', 'error');
      }
    } catch (err) {
      showMessage('申請エラー: ' + err.message, 'error');
    }
  });

  // ===== キャンセル処理 =====
  cancelBtn.addEventListener('click', () => {
    resetForm();
    currentContract = null;
    currentContractDisplay.innerHTML = '<div style="color: var(--text-muted); padding: 16px; text-align: center;">契約を検索してください</div>';
    searchInput.value = '';
    showMessage('入力内容をクリアしました', 'info');
  });

  // ===== イベントリスナー登録 =====
  searchBtn.addEventListener('click', searchContract);
  searchInput.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') searchContract();
  });

  // ===== 初期化完了 =====
  console.log('契約変更情報入力画面 初期化完了');
}

function(container, apiUrl, tables) {
  const contractSelect = container.querySelector('select[name="contractId"]');
  const invoiceSelect = container.querySelector('select[name="invoiceId"]');
  const verificationResultSelect = container.querySelector('select[name="verificationResult"]');
  const discrepancyReasonTA = container.querySelector('textarea[name="discrepancyReason"]');
  const verificationCommentTA = container.querySelector('textarea[name="verificationComment"]');

  const approveBtn = container.querySelector('[data-testid="approve-button"]');
  const rejectBtn = container.querySelector('[data-testid="reject-button"]');
  const holdBtn = container.querySelector('[data-testid="hold-button"]');

  const messageContainer = container.querySelector('#message-container');

  // テーブルインデックス（tables 配列内の位置）
  const contractTableIdx = 0;
  const invoiceTableIdx = 1;
  const invoiceDetailTableIdx = 2;
  const contractHistoryTableIdx = 3;
  const verificationLogTableIdx = 4;

  // メッセージ表示ユーティリティ
  function showMessage(text, type = 'info') {
    const msg = document.createElement('div');
    msg.style.cssText = `
      padding: 10px 14px;
      border-radius: 4px;
      font-size: 12px;
      animation: slideIn 0.3s ease-out;
      ${type === 'success' ? 'background: rgba(76,175,80,0.2); color: #4caf50; border: 1px solid rgba(76,175,80,0.4);' : ''}
      ${type === 'error' ? 'background: rgba(244,67,54,0.2); color: #f44336; border: 1px solid rgba(244,67,54,0.4);' : ''}
      ${type === 'info' ? 'background: rgba(33,150,243,0.2); color: #2196f3; border: 1px solid rgba(33,150,243,0.4);' : ''}
    `;
    msg.textContent = text;
    messageContainer.appendChild(msg);
    setTimeout(() => msg.remove(), 4000);
  }

  // 初期データロード
  async function loadInitialData() {
    try {
      const contracts = await window.aivicApi.list(contractTableIdx);
      const invoices = await window.aivicApi.list(invoiceTableIdx);

      if (contracts && contracts.length > 0) {
        contractSelect.innerHTML = '<option value="">選択してください</option>';
        contracts.forEach(c => {
          const opt = document.createElement('option');
          opt.value = c.id || c.contractId;
          opt.textContent = `${c.contractName || '契約'} (${c.contractStatus || 'ステータス不明'})`;
          contractSelect.appendChild(opt);
        });
      }

      if (invoices && invoices.length > 0) {
        invoiceSelect.innerHTML = '<option value="">選択してください</option>';
        invoices.forEach(inv => {
          const opt = document.createElement('option');
          opt.value = inv.id || inv.invoiceId;
          opt.textContent = `${inv.invoiceYearMonth || '年月不明'} - ¥${(inv.invoiceAmount || 0).toLocaleString()}`;
          invoiceSelect.appendChild(opt);
        });
      }
    } catch (err) {
      console.error('初期データロード失敗:', err);
    }
  }

  // 契約選択時の詳細表示
  contractSelect.addEventListener('change', async (e) => {
    const contractId = e.target.value;
    if (!contractId) {
      container.querySelector('#contract-name-display').textContent = '-';
      container.querySelector('#contract-period-display').textContent = '-';
      container.querySelector('#contract-amount-display').textContent = '-';
      container.querySelector('#contract-status-display').textContent = '-';
      return;
    }

    try {
      const contracts = await window.aivicApi.list(contractTableIdx);
      const contract = contracts.find(c => (c.id || c.contractId) === contractId);

      if (contract) {
        container.querySelector('#contract-name-display').textContent = contract.contractName || '-';
        const startDate = contract.contractStartDate ? new Date(contract.contractStartDate).toLocaleDateString('ja-JP') : '-';
        const endDate = contract.contractEndDate ? new Date(contract.contractEndDate).toLocaleDateString('ja-JP') : '-';
        container.querySelector('#contract-period-display').textContent = `${startDate} ～ ${endDate}`;
        container.querySelector('#contract-amount-display').textContent = `¥${(contract.contractAmount || 0).toLocaleString()}`;
        container.querySelector('#contract-status-display').textContent = contract.contractStatus || '-';

        // 契約履歴を表示
        await loadContractHistory(contractId);
      }
    } catch (err) {
      console.error('契約詳細ロード失敗:', err);
    }
  });

  // 請求選択時の明細表示
  invoiceSelect.addEventListener('change', async (e) => {
    const invoiceId = e.target.value;
    if (!invoiceId) {
      container.querySelector('#invoice-details-tbody').innerHTML = '<tr><td colspan="2" style="padding: 8px; color: var(--text-muted); text-align: center;">請求を選択してください</td></tr>';
      return;
    }

    try {
      const invoiceDetails = await window.aivicApi.list(invoiceDetailTableIdx);
      const details = invoiceDetails.filter(d => (d.invoiceId || d.id) === invoiceId);

      if (details.length > 0) {
        let total = 0;
        const rows = details.map(d => {
          const amount = d.amount || (d.quantity * d.unitPrice) || 0;
          total += amount;
          return `
            <tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
              <td style="padding: 4px; color: var(--text-muted);">${d.description || d.itemType || '項目'}</td>
              <td style="text-align: right; padding: 4px; color: var(--text);">¥${amount.toLocaleString()}</td>
            </tr>
          `;
        }).join('');

        rows += `
          <tr style="border-bottom: 1px solid rgba(255,255,255,0.1); background: rgba(255,165,0,0.08);">
            <td style="padding: 4px; color: var(--text); font-weight: 600;">合計</td>
            <td style="text-align: right; padding: 4px; color: var(--primary); font-weight: 600;">¥${total.toLocaleString()}</td>
          </tr>
        `;
        container.querySelector('#invoice-details-tbody').innerHTML = rows;
      }
    } catch (err) {
      console.error('請求明細ロード失敗:', err);
    }
  });

  // 契約履歴ロード
  async function loadContractHistory(contractId) {
    try {
      const histories = await window.aivicApi.list(contractHistoryTableIdx);
      const contractHistories = histories.filter(h => (h.contractId || h.id) === contractId).slice(0, 5);

      const timelineHtml = contractHistories.map(h => {
        const changeType = h.changeType || '変更';
        const beforeVal = h.beforeValue || '-';
        const afterVal = h.afterValue || '-';
        const createdAt = h.createdAt ? new Date(h.createdAt).toLocaleDateString('ja-JP') : '-';
        const creatorName = h.creatorName || '不明';

        return `
          <div style="padding: 6px; border-left: 2px solid var(--primary); background: rgba(255,165,0,0.08);">
            <div style="color: var(--text); font-weight: 500;">${changeType}</div>
            <div style="color: var(--text-muted); margin-top: 2px; font-size: 10px;">${beforeVal} → ${afterVal}</div>
            <div style="color: var(--text-muted); font-size: 9px; margin-top: 2px;">${createdAt} by ${creatorName}</div>
          </div>
        `;
      }).join('');

      container.querySelector('#contract-history-timeline').innerHTML = timelineHtml || '<div style="color: var(--text-muted); font-size: 11px;">履歴なし</div>';
    } catch (err) {
      console.error('契約履歴ロード失敗:', err);
    }
  }

  // 承認処理
  approveBtn.addEventListener('click', async () => {
    const contractId = contractSelect.value;
    const invoiceId = invoiceSelect.value;
    const result = verificationResultSelect.value;
    const comment = verificationCommentTA.value.trim();

    if (!contractId || !invoiceId || !result) {
      showMessage('契約、請求、検証結果を選択してください', 'error');
      return;
    }

    try {
      const verificationRecord = {
        contractId,
        invoiceId,
        verificationResult: result,
        discrepancyReason: discrepancyReasonTA.value.trim(),
        verificationComment: comment,
        verificationStatus: 'approved',
        approvedAt: new Date().toISOString(),
        approvedBy: 'current-user-id'
      };

      const saved = await window.aivicApi.save(verificationLogTableIdx, verificationRecord);
      if (saved) {
        showMessage('検証結果を承認しました', 'success');
        setTimeout(() => {
          contractSelect.value = '';
          invoiceSelect.value = '';
          verificationResultSelect.value = '';
          discrepancyReasonTA.value = '';
          verificationCommentTA.value = '';
        }, 1000);
      }
    } catch (err) {
      console.error('承認処理失敗:', err);
      showMessage('承認処理に失敗しました', 'error');
    }
  });

  // 却下処理
  rejectBtn.addEventListener('click', async () => {
    const contractId = contractSelect.value;
    const invoiceId = invoiceSelect.value;
    const comment = verificationCommentTA.value.trim();

    if (!contractId || !invoiceId) {
      showMessage('契約と請求を選択してください', 'error');
      return;
    }

    if (!comment) {
      showMessage('却下理由を記入してください', 'error');
      return;
    }

    try {
      const verificationRecord = {
        contractId,
        invoiceId,
        verificationResult: 'rejected',
        verificationComment: comment,
        verificationStatus: 'rejected',
        rejectedAt: new Date().toISOString(),
        rejectedBy: 'current-user-id'
      };

      const saved = await window.aivicApi.save(verificationLogTableIdx, verificationRecord);
      if (saved) {
        showMessage('検証結果を却下しました', 'success');
        setTimeout(() => {
          contractSelect.value = '';
          invoiceSelect.value = '';
          verificationResultSelect.value = '';
          discrepancyReasonTA.value = '';
          verificationCommentTA.value = '';
        }, 1000);
      }
    } catch (err) {
      console.error('却下処理失敗:', err);
      showMessage('却下処理に失敗しました', 'error');
    }
  });

  // 保留処理
  holdBtn.addEventListener('click', async () => {
    const contractId = contractSelect.value;
    const invoiceId = invoiceSelect.value;
    const comment = verificationCommentTA.value.trim();

    if (!contractId || !invoiceId) {
      showMessage('契約と請求を選択してください', 'error');
      return;
    }

    try {
      const verificationRecord = {
        contractId,
        invoiceId,
        verificationResult: 'pending',
        verificationComment: comment,
        verificationStatus: 'pending',
        heldAt: new Date().toISOString(),
        heldBy: 'current-user-id'
      };

      const saved = await window.aivicApi.save(verificationLogTableIdx, verificationRecord);
      if (saved) {
        showMessage('検証結果を保留しました', 'success');
        setTimeout(() => {
          contractSelect.value = '';
          invoiceSelect.value = '';
          verificationResultSelect.value = '';
          discrepancyReasonTA.value = '';
          verificationCommentTA.value = '';
        }, 1000);
      }
    } catch (err) {
      console.error('保留処理失敗:', err);
      showMessage('保留処理に失敗しました', 'error');
    }
  });

  // 初期化実行
  loadInitialData();
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const contractTableIdx = tables.findIndex(t => t.tableName === '契約');
  const customerTableIdx = tables.findIndex(t => t.tableName === '顧客');
  const discountTableIdx = tables.findIndex(t => t.tableName === '割引基準');

  // DOM 要素
  const customerIdInput = container.querySelector('[data-testid="customer-id-input"]');
  const customerNameInput = container.querySelector('[data-testid="customer-name-input"]');
  const searchBtn = container.querySelector('[data-testid="search-button"]');
  const contractTbody = container.querySelector('#contract-tbody');
  const contractDetailPanel = container.querySelector('#contract-detail-panel');
  const contractDetailEmpty = container.querySelector('#contract-detail-empty');
  const discountPanel = container.querySelector('#discount-panel');
  const discountEmpty = container.querySelector('#discount-empty');
  const verifyBtn = container.querySelector('[data-testid="verify-button"]');
  const billingBtn = container.querySelector('[data-testid="billing-button"]');
  const changeRequestBtn = container.querySelector('[data-testid="change-request-button"]');
  const viewHistoryBtn = container.querySelector('[data-testid="view-history-button"]');

  let currentCustomerId = null;
  let currentContractId = null;

  // 検索実行
  async function performSearch() {
    const customerId = customerIdInput.value.trim();
    const customerName = customerNameInput.value.trim();

    if (!customerId && !customerName) {
      alert('顧客IDまたは顧客名を入力してください');
      return;
    }

    // 顧客データ取得
    const customers = await window.aivicApi.list(customerTableIdx);
    if (!customers) return;

    let matchedCustomer = null;
    if (customerId) {
      matchedCustomer = customers.find(c => c.顧客ID === customerId);
    } else if (customerName) {
      matchedCustomer = customers.find(c => c.顧客名 && c.顧客名.includes(customerName));
    }

    if (!matchedCustomer) {
      alert('該当する顧客が見つかりません');
      contractTbody.innerHTML = '<tr style="border-bottom: 1px solid rgba(255,255,255,0.08);"><td colspan="4" style="padding: 12px; text-align: center; color: var(--text-muted);">該当する顧客がありません</td></tr>';
      currentCustomerId = null;
      return;
    }

    currentCustomerId = matchedCustomer.顧客ID;

    // 契約データ取得
    const contracts = await window.aivicApi.list(contractTableIdx);
    if (!contracts) return;

    // 顧客に紐付く契約をフィルタ
    const customerContracts = contracts.filter(c => c.顧客企業ID === currentCustomerId);

    if (customerContracts.length === 0) {
      contractTbody.innerHTML = '<tr style="border-bottom: 1px solid rgba(255,255,255,0.08);"><td colspan="4" style="padding: 12px; text-align: center; color: var(--text-muted);">契約がありません</td></tr>';
      return;
    }

    // テーブル描画
    contractTbody.innerHTML = customerContracts.map(contract => `
      <tr 
        data-id="${contract.契約ID}" 
        style="border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer; transition: background 0.2s;"
        onmouseover="this.style.background='rgba(255,255,255,0.05)'"
        onmouseout="this.style.background=''"
      >
        <td style="padding: 6px; font-size: 11px; color: var(--text);">${contract.契約ID || '—'}</td>
        <td style="padding: 6px; font-size: 11px; color: var(--text);">${contract.契約開始日 ? new Date(contract.契約開始日).toLocaleDateString('ja-JP') : '—'}</td>
        <td style="padding: 6px; font-size: 11px; color: var(--text);">${contract.契約終了日 ? new Date(contract.契約終了日).toLocaleDateString('ja-JP') : '—'}</td>
        <td style="padding: 6px; font-size: 11px; color: var(--text);">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${getStatusColor(contract.契約ステータス)}; color: #fff; font-size: 10px;">
            ${contract.契約ステータス || '—'}
          </span>
        </td>
      </tr>
    `).join('');

    // 行クリックイベント
    contractTbody.querySelectorAll('tr[data-id]').forEach(row => {
      row.addEventListener('click', () => {
        const contractId = row.dataset.id;
        selectContract(contractId, customerContracts);
      });
    });

    // 詳細パネルをリセット
    contractDetailEmpty.style.display = 'block';
    contractDetailPanel.style.display = 'none';
    discountEmpty.style.display = 'block';
    discountPanel.style.display = 'none';
  }

  // 契約選択
  async function selectContract(contractId, contracts) {
    currentContractId = contractId;
    const contract = contracts.find(c => c.契約ID === contractId);
    if (!contract) return;

    // 詳細パネル表示
    container.querySelector('#detail-contract-id').textContent = contract.契約ID || '—';
    container.querySelector('#detail-contract-name').textContent = contract.契約名 || '—';
    container.querySelector('#detail-start-date').textContent = contract.契約開始日 ? new Date(contract.契約開始日).toLocaleDateString('ja-JP') : '—';
    container.querySelector('#detail-end-date').textContent = contract.契約終了日 ? new Date(contract.契約終了日).toLocaleDateString('ja-JP') : '—';
    container.querySelector('#detail-amount').textContent = contract.契約金額 ? `¥${contract.契約金額.toLocaleString()}` : '—';
    container.querySelector('#detail-status').textContent = contract.契約ステータス || '—';
    container.querySelector('#detail-content').textContent = contract.契約内容 || '—';
    container.querySelector('#detail-goal').textContent = contract.成果目標 || '—';

    contractDetailEmpty.style.display = 'none';
    contractDetailPanel.style.display = 'block';

    // 割引基準情報取得
    const discounts = await window.aivicApi.list(discountTableIdx);
    if (!discounts) {
      discountEmpty.style.display = 'block';
      discountPanel.style.display = 'none';
      return;
    }

    const discount = discounts.find(d => d.契約ID === contractId);
    if (!discount) {
      discountEmpty.style.display = 'block';
      discountPanel.style.display = 'none';
      return;
    }

    // 割引基準パネル表示
    container.querySelector('#discount-type').textContent = discount.割引種別 || '—';
    container.querySelector('#discount-value').textContent = discount.割引率 ? `${discount.割引率}%` : (discount.割引額 ? `¥${discount.割引額.toLocaleString()}` : '—');
    container.querySelector('#discount-condition').textContent = discount.適用条件 || '—';
    container.querySelector('#discount-start').textContent = discount.適用開始日 ? new Date(discount.適用開始日).toLocaleDateString('ja-JP') : '—';
    container.querySelector('#discount-end').textContent = discount.適用終了日 ? new Date(discount.適用終了日).toLocaleDateString('ja-JP') : '—';

    discountEmpty.style.display = 'none';
    discountPanel.style.display = 'block';
  }

  // ステータス色
  function getStatusColor(status) {
    const colors = {
      '提案中': '#ff9800',
      '承認待ち': '#2196f3',
      '契約済': '#4caf50',
      '完了': '#9c27b0',
      '終了': '#f44336'
    };
    return colors[status] || '#757575';
  }

  // イベントリスナー
  searchBtn.addEventListener('click', performSearch);
  customerIdInput.addEventListener('keypress', e => {
    if (e.key === 'Enter') performSearch();
  });
  customerNameInput.addEventListener('keypress', e => {
    if (e.key === 'Enter') performSearch();
  });

  // 請求検証画面へ遷移
  verifyBtn.addEventListener('click', () => {
    if (!currentContractId) {
      alert('契約を選択してください');
      return;
    }
