function(container, apiUrl, tables) {
  // テーブルインデックス
  const INVOICE_TABLE_IDX = 0;
  const INVOICE_DETAIL_TABLE_IDX = 1;
  const CONTRACT_TABLE_IDX = 2;
  const CUSTOMER_TABLE_IDX = 3;

  // 現在の請求ID（URL パラメータから取得、またはテスト用にローカルストレージから）
  let currentInvoiceId = new URLSearchParams(window.location.search).get('invoiceId') 
    || localStorage.getItem('currentInvoiceId');

  // DOM 要素
  const invoiceNumberEl = container.querySelector('[data-testid="invoice-number"]');
  const customerNameEl = container.querySelector('[data-testid="customer-name"]');
  const contractNumberEl = container.querySelector('[data-testid="contract-number"]');
  const invoiceDateEl = container.querySelector('[data-testid="invoice-date"]');
  const invoicePeriodEl = container.querySelector('[data-testid="invoice-period"]');
  const dueDateEl = container.querySelector('[data-testid="due-date"]');
  const invoiceAmountEl = container.querySelector('[data-testid="invoice-amount"]');
  const remarksEl = container.querySelector('[data-testid="remarks"]');
  const detailsTbody = container.querySelector('#invoice-details-tbody');
  const subtotalEl = container.querySelector('[data-testid="subtotal"]');
  const totalTaxEl = container.querySelector('[data-testid="total-tax"]');

  const approveBtn = container.querySelector('[data-testid="approve-button"]');
  const rejectBtn = container.querySelector('[data-testid="reject-button"]');
  const backBtn = container.querySelector('[data-testid="back-button"]');

  const rejectModal = container.querySelector('#reject-modal');
  const rejectReasonEl = container.querySelector('#reject-reason');
  const rejectCancelBtn = container.querySelector('#reject-cancel-btn');
  const rejectConfirmBtn = container.querySelector('#reject-confirm-btn');

  const approveModal = container.querySelector('#approve-modal');
  const approveCancelBtn = container.querySelector('#approve-cancel-btn');
  const approveConfirmBtn = container.querySelector('#approve-confirm-btn');

  const successMsg = container.querySelector('#success-message');
  const errorMsg = container.querySelector('#error-message');

  // ユーティリティ関数
  function formatDate(dateStr) {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    return date.toLocaleDateString('ja-JP', { year: 'numeric', month: '2-digit', day: '2-digit' });
  }

  function formatCurrency(amount) {
    if (amount === null || amount === undefined) return '¥0';
    return '¥' + amount.toLocaleString('ja-JP');
  }

  function showNotification(type, message) {
    const el = type === 'success' ? successMsg : errorMsg;
    el.textContent = message;
    el.style.display = 'block';
    setTimeout(() => {
      el.style.display = 'none';
    }, 3000);
  }

  // 請求情報を読み込んで表示
  async function loadInvoiceData() {
    if (!currentInvoiceId) {
      showNotification('error', '請求IDが指定されていません');
      return;
    }

    try {
      // 請求データ取得
      const invoices = await window.aivicApi.list(INVOICE_TABLE_IDX);
      const invoice = invoices.find(inv => inv.id === currentInvoiceId);
      if (!invoice) {
        showNotification('error', '請求情報が見つかりません');
        return;
      }

      // 契約データ取得
      const contracts = await window.aivicApi.list(CONTRACT_TABLE_IDX);
      const contract = contracts.find(c => c.id === invoice.contractId);

      // 顧客データ取得
      const customers = await window.aivicApi.list(CUSTOMER_TABLE_IDX);
      const customer = customers.find(cust => cust.id === contract?.customerCompanyId);

      // ヘッダー情報を表示
      invoiceNumberEl.textContent = invoice.id?.substring(0, 8).toUpperCase() || '-';
      customerNameEl.textContent = customer?.customerName || '-';
      contractNumberEl.textContent = contract?.id?.substring(0, 8).toUpperCase() || '-';
      invoiceDateEl.textContent = formatDate(invoice.invoiceDate);
      invoicePeriodEl.textContent = invoice.invoiceYearMonth ? 
        `${invoice.invoiceYearMonth.substring(0, 4)}年${invoice.invoiceYearMonth.substring(5, 7)}月` : '-';
      dueDateEl.textContent = formatDate(invoice.paymentDueDate);
      invoiceAmountEl.textContent = formatCurrency(invoice.invoiceAmount);
      remarksEl.textContent = invoice.remarks || '-';

      // 請求明細を読み込んで表示
      const details = await window.aivicApi.list(INVOICE_DETAIL_TABLE_IDX);
      const invoiceDetails = details.filter(d => d.invoiceId === currentInvoiceId);

      if (invoiceDetails.length === 0) {
        detailsTbody.innerHTML = '<tr style="border-bottom: 1px solid rgba(255,255,255,0.08);"><td colspan="7" style="padding: 12px; text-align: center; color: var(--text-muted);">明細がありません</td></tr>';
        subtotalEl.textContent = '¥0';
        totalTaxEl.textContent = '¥0';
        return;
      }

      // 明細テーブルを描画
      let subtotal = 0;
      let totalTax = 0;

      detailsTbody.innerHTML = invoiceDetails.map(detail => {
        const amount = detail.amount || 0;
        const taxAmount = detail.taxAmount || 0;
        subtotal += amount;
        totalTax += taxAmount;

        return `
          <tr style="border-bottom: 1px solid rgba(255,255,255,0.08);">
            <td style="padding: 8px; color: var(--text); font-size: 12px;">${detail.detailType || '-'}</td>
            <td style="padding: 8px; color: var(--text); font-size: 12px;">${detail.description || '-'}</td>
            <td style="padding: 8px; text-align: right; color: var(--text); font-size: 12px;">${detail.quantity || 0}</td>
            <td style="padding: 8px; text-align: right; color: var(--text); font-size: 12px;">${formatCurrency(detail.unitPrice)}</td>
            <td style="padding: 8px; text-align: right; color: var(--text); font-size: 12px; font-weight: 600;">${formatCurrency(amount)}</td>
            <td style="padding: 8px; text-align: right; color: var(--text); font-size: 12px;">${detail.taxRate || 0}%</td>
            <td style="padding: 8px; text-align: right; color: #ff6a00; font-size: 12px; font-weight: 600;">${formatCurrency(taxAmount)}</td>
          </tr>
        `;
      }).join('');

      subtotalEl.textContent = formatCurrency(subtotal);
      totalTaxEl.textContent = formatCurrency(totalTax);

    } catch (error) {
      console.error('請求データ読み込みエラー:', error);
      showNotification('error', 'データの読み込みに失敗しました');
    }
  }

  // 承認処理
  async function approveInvoice() {
    try {
      await window.aivicApi.update(INVOICE_TABLE_IDX, currentInvoiceId, {
        invoiceStatus: 'approved'
      });
      showNotification('success', '請求を承認しました');
      approveModal.style.display = 'none';
      setTimeout(() => {
        window.showScreen('scr-1782113529179'); // 請求検証管理画面へ遷移
      }, 1500);
    } catch (error) {
      console.error('承認エラー:', error);
      showNotification('error', '承認に失敗しました');
    }
  }

  // 却下処理
  async function rejectInvoice() {
    const reason = rejectReasonEl.value.trim();
    if (!reason) {
      showNotification('error', '却下理由を入力してください');
      return;
    }

    try {
      await window.aivicApi.update(INVOICE_TABLE_IDX, currentInvoiceId, {
        invoiceStatus: 'rejected',
        remarks: reason
      });
      showNotification('success', '請求を却下しました');
      rejectModal.style.display = 'none';
      setTimeout(() => {
        window.showScreen('scr-1782113529179'); // 請求検証管理画面へ遷移
      }, 1500);
    } catch (error) {
      console.error('却下エラー:', error);
      showNotification('error', '却下に失敗しました');
    }
  }

  // イベントリスナー
  approveBtn.addEventListener('click', () => {
    approveModal.style.display = 'flex';
  });

  approveCancelBtn.addEventListener('click', () => {
    approveModal.style.display = 'none';
  });

  approveConfirmBtn.addEventListener('click', approveInvoice);

  rejectBtn.addEventListener('click', () => {
    rejectReasonEl.value = '';
    rejectModal.style.display = 'flex';
  });

  rejectCancelBtn.addEventListener('click', () => {
    rejectModal.style.display = 'none';
  });

  rejectConfirmBtn.addEventListener('click', rejectInvoice);

  backBtn.addEventListener('click', () => {
    window.showScreen('scr-1782113529179'); // 請求検証管理画面へ遷移
  });

  // 初期化
  loadInvoiceData();
}
